// Pins T12 (read) and T13 (write, REWRITTEN this session to surgical OOXML
// edits — see xlsx-comments.ts's own header for why) of the doc-comments
// build (docs/active/specs/2026-09-26-doc-comments-build-design.md
// §4.1-§4.3, §8): reading and writing Excel legacy cell Notes off a REAL
// .xlsx, in the Electron main process.
//
// Fixtures:
// - tests/fixtures/doc-comments/q3-sales-by-rep.xlsx, generated by
//   tests/fixtures/doc-comments/make-xlsx-fixture.mjs — a real workbook
//   exceljs itself wrote, with eight real Notes across two sheets. Used for
//   the READ pinning tests and ordinary write-path behaviour.
// - tests/fixtures/doc-comments/xlsx-kitchen-sink.xlsx, generated by
//   tests/fixtures/doc-comments/build-xlsx-kitchen-sink.py — a real workbook
//   LibreOffice itself wrote (via its own UNO scripting API, not exceljs),
//   carrying exactly the OOXML surface the OLD exceljs-based writer was
//   proven to lose on round-trip: a custom document property, a defined name
//   with an absolute (`$`) reference, merged cells, custom column widths, a
//   hidden row, frozen panes, conditional formatting, data validation, a
//   hyperlink, an embedded image, sheet protection, rich text, and a
//   PRE-EXISTING, deliberately resized legacy comment on Data!E1. Used for
//   the byte-identity pinning tests below — the whole point of this
//   session's rewrite.
import { describe, it, expect } from 'vitest';
import { readFile, writeFile, mkdtemp, rm, readdir } from 'fs/promises';
import { join, dirname } from 'path';
import { tmpdir } from 'os';
import { execFile } from 'child_process';
import { promisify } from 'util';
import JSZip from 'jszip';
import {
  readXlsxComments,
  addXlsxComment,
  replyToXlsxComment,
  resolveXlsxComment,
  reopenXlsxComment,
  moveXlsxComment,
} from '../src/main/doc-comments/xlsx-comments';
import { backupPathFor } from '../src/main/doc-comments/write-pipeline';
import { buildDeclaredOversizeZip, buildRealZipBomb } from './fixtures/doc-comments/oversized-zip';
import type { CommentSelector } from '../src/shared/doc-comments-types';

const execFileAsync = promisify(execFile);

const FIXTURE = join(__dirname, 'fixtures', 'doc-comments', 'q3-sales-by-rep.xlsx');
const KITCHEN_SINK_FIXTURE = join(__dirname, 'fixtures', 'doc-comments', 'xlsx-kitchen-sink.xlsx');

async function loadFixture(): Promise<Buffer> {
  return readFile(FIXTURE);
}

async function loadKitchenSinkFixture(): Promise<Buffer> {
  return readFile(KITCHEN_SINK_FIXTURE);
}

function cellSelector(cell: string, sheet?: string): CommentSelector {
  return { kind: 'cell', selector: { type: 'CellSelector', cell, ...(sheet ? { sheet } : {}) } };
}

/** `{author, text}` only — a `CommentReply.id` is derived from its parent
 *  comment's OWN (cell-address-derived) id, and `createdAt` is a fresh
 *  `Date.now()` stamped on every READ (§4's own reader has no per-reply
 *  timestamp to persist) — neither survives a move, or even a second read a
 *  few milliseconds later, so comparing replies across two reads or across a
 *  move must ignore both rather than asserting on incidental values. */
function repliesShape(replies: ReadonlyArray<{ author: string; text: string }>) {
  return replies.map((r) => ({ author: r.author, text: r.text }));
}

async function withScratchCopy<T>(fn: (target: string) => Promise<T>, bytes?: Buffer, name = 'q3-sales-by-rep.xlsx'): Promise<T> {
  const dir = await mkdtemp(join(tmpdir(), 'ycd-xlsx-write-'));
  const target = join(dir, name);
  await writeFile(target, bytes ?? (await loadFixture()));
  try {
    return await fn(target);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
}

async function withKitchenSinkScratchCopy<T>(fn: (target: string) => Promise<T>): Promise<T> {
  return withScratchCopy(fn, await loadKitchenSinkFixture(), 'xlsx-kitchen-sink.xlsx');
}

/** Injects a fake OOXML part into the real fixture's own bytes — used only to
 *  prove `unsupported-workbook-features` trips on the entry NAME, never on
 *  its (here, deliberately nonsensical) content. Charts are no longer
 *  refused by this rewrite (see xlsx-comments.ts's own header for why a
 *  surgical writer never needs to) — `withFakeChartPart` is kept only to
 *  prove that NEGATIVE ("charts round-trip fine now") below. Modern threaded
 *  comments are the one feature still refused. */
async function withFakeChartPart(): Promise<Buffer> {
  const zip = await JSZip.loadAsync(await loadFixture());
  zip.file('xl/charts/chart1.xml', '<c:chartSpace/>');
  return zip.generateAsync({ type: 'nodebuffer' });
}

async function withFakeThreadedCommentsPart(): Promise<Buffer> {
  const zip = await JSZip.loadAsync(await loadFixture());
  zip.file('xl/threadedComments/threadedComment1.xml', '<ThreadedComments/>');
  return zip.generateAsync({ type: 'nodebuffer' });
}

/** Every entry name in a zip, sorted — used to diff which parts an operation
 *  actually touched. */
async function zipEntryNames(bytes: Buffer): Promise<string[]> {
  const zip = await JSZip.loadAsync(bytes);
  const names: string[] = [];
  zip.forEach((relPath, file) => {
    if (!file.dir) names.push(relPath);
  });
  return names.sort();
}

/** Asserts every entry in `before`/`after` is byte-identical EXCEPT the ones
 *  named in `expectedChangedOrNew` (an operation may also ADD a brand-new
 *  part, e.g. a worksheet's first-ever comments/vmlDrawing pair — those are
 *  allowed to be present in `after` only). This is the task's own "every
 *  part except the comment-related ones is byte-identical" contract, made
 *  concrete and machine-checkable. */
async function assertOnlyThesePartsChanged(before: Buffer, after: Buffer, expectedChangedOrNew: readonly string[]): Promise<void> {
  const beforeZip = await JSZip.loadAsync(before);
  const afterZip = await JSZip.loadAsync(after);
  const beforeNames = await zipEntryNames(before);
  const allowed = new Set(expectedChangedOrNew);
  for (const name of beforeNames) {
    if (allowed.has(name)) continue;
    const beforeFile = beforeZip.file(name);
    const afterFile = afterZip.file(name);
    expect(afterFile, `part "${name}" was REMOVED by the write`).not.toBeNull();
    const [beforeText, afterText] = await Promise.all([beforeFile!.async('string'), afterFile!.async('string')]);
    expect(afterText, `part "${name}" was NOT supposed to change but did`).toBe(beforeText);
  }
}

/** Confirms `bytes` (an already-written .xlsx) opens cleanly in a REAL
 *  LibreOffice, converting to PDF and checking a non-empty file came out —
 *  the task's own "every output opens in LibreOffice" external-validation
 *  requirement. Skips gracefully (rather than failing) if `soffice` isn't on
 *  PATH in whatever environment runs this suite, since that's an environment
 *  fact, not a regression in this module. */
async function assertOpensInLibreOffice(bytes: Buffer): Promise<void> {
  const dir = await mkdtemp(join(tmpdir(), 'ycd-xlsx-lo-check-'));
  try {
    const input = join(dir, 'check.xlsx');
    await writeFile(input, bytes);
    try {
      await execFileAsync('soffice', ['--headless', '--norestore', '--convert-to', 'pdf', '--outdir', dir, input], {
        timeout: 60_000,
      });
    } catch (e: any) {
      if (e?.code === 'ENOENT') return; // soffice not installed in this environment — not this module's concern
      throw e;
    }
    const pdfBytes = await readFile(join(dir, 'check.pdf'));
    expect(pdfBytes.length).toBeGreaterThan(0);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
}

describe('xlsx-comments — parsing a workbook with a .note set', () => {
  it('reads the plain note on the FIRST sheet', async () => {
    const bytes = await loadFixture();
    const result = await readXlsxComments(bytes, 'reports/q3-sales-by-rep.xlsx');
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const q3Note = result.comments.find((c) => c.selector.kind === 'cell' && c.selector.selector.cell === 'B2');
    expect(q3Note).toBeDefined();
    expect(q3Note?.author).toBe('person:Priya Shah');
    expect(q3Note?.text).toContain('West is Priya');
    expect(q3Note?.resolved).toBe(false);
    expect(q3Note?.replies).toEqual([]);
    expect(q3Note?.path).toBe('reports/q3-sales-by-rep.xlsx');
  });
});

describe('xlsx-comments — multi-sheet cell targeting', () => {
  it('finds a note on a NON-FIRST sheet, naming that sheet on the selector', async () => {
    const bytes = await loadFixture();
    const result = await readXlsxComments(bytes, 'reports/q3-sales-by-rep.xlsx');
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const byRepNote = result.comments.find((c) => c.selector.kind === 'cell' && c.selector.selector.cell === 'B4');
    expect(byRepNote).toBeDefined();
    if (byRepNote?.selector.kind !== 'cell') throw new Error('expected a cell selector');
    // A multi-tab workbook stamps the sheet name (§4.2: required only when
    // there's more than one tab) — never assumes sheet 0.
    expect(byRepNote.selector.selector.sheet).toBe('By rep');
    expect(byRepNote.text).toContain('North looks low for July');
  });

  it('does not mistake the first sheet for the whole workbook', async () => {
    const bytes = await loadFixture();
    const result = await readXlsxComments(bytes, 'reports/q3-sales-by-rep.xlsx');
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    // Eight real notes total, spread across both sheets (B2/B18/B19/B20 on
    // Q3, B4/B5/B6/B7 on By rep) — a reader that only looked at worksheet 0
    // would report far fewer.
    expect(result.comments).toHaveLength(8);
  });
});

describe('xlsx-comments — reply threads and the resolve marker', () => {
  it('splits a multi-turn note into the original comment plus its replies', async () => {
    const bytes = await loadFixture();
    const result = await readXlsxComments(bytes, 'reports/q3-sales-by-rep.xlsx');
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const threaded = result.comments.find((c) => c.selector.kind === 'cell' && c.selector.selector.cell === 'B5');
    expect(threaded).toBeDefined();
    expect(threaded?.author).toBe('person:Priya Shah');
    expect(threaded?.text).toContain('Diego’s numbers look great');
    expect(threaded?.replies).toHaveLength(1);
    expect(threaded?.replies[0]).toMatchObject({
      author: 'person:Marcus Lee',
      text: expect.stringContaining('Agreed'),
    });
  });

  it('reads the resolve marker as resolved: true, and strips it from the text', async () => {
    const bytes = await loadFixture();
    const result = await readXlsxComments(bytes, 'reports/q3-sales-by-rep.xlsx');
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    const threaded = result.comments.find((c) => c.selector.kind === 'cell' && c.selector.selector.cell === 'B5');
    expect(threaded?.resolved).toBe(true);
    expect(threaded?.replies[0].text).not.toContain('yc:resolved');
    expect(threaded?.replies[0].text).not.toContain('​');
  });

  it('does NOT read resolve-like natural language as the resolve marker', async () => {
    const bytes = await loadFixture();
    const result = await readXlsxComments(bytes, 'reports/q3-sales-by-rep.xlsx');
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    const q3Note = result.comments.find((c) => c.selector.kind === 'cell' && c.selector.selector.cell === 'B2');
    // This note's text has nothing resolve-like in it, and in particular is
    // NOT flagged resolved just because a reader might loosely scan for the
    // word "resolved" anywhere in the body — only the exact machine token
    // triggers it (a plain string note like this one has none).
    expect(q3Note?.resolved).toBe(false);
  });
});

// F2 (implementation review — parity): a workbook with one real worksheet
// plus one CHARTSHEET must stay "single-sheet" — exceljs's own `reconcile()`
// never surfaces a chartsheet as a worksheet at all (this file's own header,
// T13 section), so `workbook.worksheets.length` already excludes it here.
// The shared fixture (`chartsheet-workbook.xlsx`, `make-xlsx-chartsheet-
// fixture.mjs`) and this exact assertion are what Android's `XlsxComments.kt`
// own golden-parity test (`chartsheetWorkbookMatchesTheDesktopReaderFieldFor
// FieldAndStaysSingleSheet`) is pinned against — see that fixture generator's
// own header for why exceljs can't write a chartsheet itself.
describe('xlsx-comments — a workbook with a worksheet AND a chartsheet', () => {
  it('never counts the chartsheet as a worksheet — stays single-sheet, no `sheet` on the selector', async () => {
    const bytes = await readFile(join(__dirname, 'fixtures', 'doc-comments', 'chartsheet-workbook.xlsx'));
    const result = await readXlsxComments(bytes, 'reports/chartsheet-workbook.xlsx');
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.comments).toHaveLength(1);
    const note = result.comments[0];
    expect(note.selector.kind).toBe('cell');
    if (note.selector.kind !== 'cell') return;
    // §4.2: `sheet` is only ever named on a genuinely multi-sheet workbook.
    expect(note.selector.selector.sheet).toBeUndefined();
    expect(note.author).toBe('person:Priya Shah');
  });
});

