describe('xlsx-comments write — verify-after-write with automatic rollback', () => {
  // The generic mechanism (backup/atomic-write/verify/rollback) is pinned
  // once, at the shared module level, in write-pipeline.test.ts — every xlsx
  // write op delegates to it identically. This test exercises the SAME
  // contract through a real xlsx write op end to end, confirming the
  // `.xlsx.bak-` backup naming this module actually uses and that a add()
  // call which fails verification leaves the real file untouched.
  it('an add whose own verify step never runs (mutate-level refusal) never creates or leaves a backup', async () => {
    await withScratchCopy(async (target) => {
      const before = await readFile(target);
      const result = await addXlsxComment({
        absolutePath: target,
        path: 'reports/q3-sales-by-rep.xlsx',
        selector: cellSelector('B2', 'Q3'), // already commented — refused before any write
        text: 'x',
        author: 'user',
      });
      expect(result).toEqual({ ok: false, error: 'cell-already-has-comment' });
      expect(await readFile(target)).toEqual(before);
      const dir = dirname(target);
      expect((await readdir(dir)).filter((f) => f.includes('.xlsx.bak-'))).toHaveLength(0);
    });
  });
});

describe('xlsx-comments write — concurrency', () => {
  it('two mutations on one file serialize, and neither is lost', async () => {
    await withScratchCopy(async (target) => {
      const [a, b] = await Promise.all([
        addXlsxComment({
          absolutePath: target,
          path: 'reports/q3-sales-by-rep.xlsx',
          selector: cellSelector('A1', 'Q3'),
          text: 'First concurrent comment.',
          author: 'user',
        }),
        addXlsxComment({
          absolutePath: target,
          path: 'reports/q3-sales-by-rep.xlsx',
          selector: cellSelector('A2', 'Q3'),
          text: 'Second concurrent comment.',
          author: 'user',
        }),
      ]);
      expect(a.ok).toBe(true);
      expect(b.ok).toBe(true);

      const read = await readXlsxComments(await readFile(target), 'reports/q3-sales-by-rep.xlsx');
      expect(read.ok).toBe(true);
      if (!read.ok) return;
      if (!a.ok || !b.ok) return;
      const first = read.comments.find((c) => c.id === a.id);
      const second = read.comments.find((c) => c.id === b.id);
      expect(first?.text).toBe('First concurrent comment.');
      expect(second?.text).toBe('Second concurrent comment.');
    });
  });
});

// F10 (implementation review, this session): the read path's "Name: text"
// author-shape heuristic also matches a colleague's own ordinary Title-Case
// heading, not just a real name — see xlsx-comments.ts's own `NON_NAME_
// HEADINGS` doc comment for why a denylist, rather than a workbook-wide
// "known author" cross-reference, is the fix that doesn't ALSO break the
// existing "Marcus Lee" (a real, single-occurrence name) pinning test above.
describe('xlsx-comments — F10: a Title-Case heading is not misread as an author', () => {
  it('"Action Items: ..." is not attributed to an author named "Action Items"', async () => {
    await withScratchCopy(async (target) => {
      const result = await addXlsxComment({
        absolutePath: target,
        path: 'reports/q3-sales-by-rep.xlsx',
        selector: cellSelector('A1', 'Q3'),
        text: 'x',
        author: 'user',
      });
      if (!result.ok) throw new Error('setup: add failed');
      // Overwrite the freshly-added comment's (ref="A1") raw body directly
      // (bypassing this app's own writer, which would never produce this
      // shape) to simulate a colleague pasting a heading like this into a
      // real note — Q3's own comments part already has several OTHER
      // comments, so the replacement is anchored to the specific
      // `<comment ref="A1">` element, never just "the first `<t>` in the
      // file" (which would hit some pre-existing comment instead).
      const zip = await JSZip.loadAsync(await readFile(target));
      let patchedName: string | null = null;
      // Attribute order on the written <comment> isn't guaranteed (linkedom
      // doesn't preserve setAttribute call order) — match `ref="A1"`
      // anywhere in the opening tag via a lookahead, never a fixed order.
      const COMMENT_A1_RE = /(<comment\b(?=[^>]*\bref="A1")[^>]*>[\s\S]*?<t[^>]*>)[^<]*(<\/t>[\s\S]*?<\/comment>)/;
      for (const file of zip.file(/xl\/comments\d+\.xml/)) {
        const xml = await file.async('string');
        if (!COMMENT_A1_RE.test(xml)) continue;
        const patched = xml.replace(COMMENT_A1_RE, '$1Action Items: buy milk and eggs$2');
        expect(patched, `expected the ref="A1" comment's <t> to be replaced in ${file.name}`).not.toBe(xml);
        zip.file(file.name, patched);
        patchedName = file.name;
      }
      expect(patchedName, 'no comments part contained ref="A1"').not.toBeNull();
      await writeFile(target, await zip.generateAsync({ type: 'nodebuffer' }));

      const read = await readXlsxComments(await readFile(target), 'reports/q3-sales-by-rep.xlsx');
      expect(read.ok).toBe(true);
      if (!read.ok) return;
      const note = read.comments.find((c) => c.id === result.id);
      expect(note?.author).toBe('person:Unknown');
      expect(note?.text).toBe('Action Items: buy milk and eggs'); // never dropped, never split
    });
  });
});

// F7 (implementation review, this session): confirm the rolling-backup
// naming (write-pipeline.ts's `backupPathFor`) really does leave NO
// orphaned timestamped `.bak` file next to the user's own workbook, and
// really does roll (one file, overwritten by the next write) rather than
// accumulating one per write.
describe('xlsx-comments write — F7: rolling backup, never orphaned next to the file', () => {
  it('a successful write leaves no sibling .bak file, and reuses the SAME backup path across writes', async () => {
    await withScratchCopy(async (target) => {
      const dir = dirname(target);
      const backupPath = backupPathFor(target, '.xlsx.bak');

      const first = await addXlsxComment({
        absolutePath: target,
        path: 'reports/q3-sales-by-rep.xlsx',
        selector: cellSelector('A1', 'Q3'),
        text: 'First.',
        author: 'user',
      });
      expect(first.ok).toBe(true);
      // No sibling .bak file next to the user's own file — ever.
      expect((await readdir(dir)).some((f) => f.includes('.bak'))).toBe(false);
      const backupAfterFirst = await readFile(backupPath);

      const second = await addXlsxComment({
        absolutePath: target,
        path: 'reports/q3-sales-by-rep.xlsx',
        selector: cellSelector('A2', 'Q3'),
        text: 'Second.',
        author: 'user',
      });
      expect(second.ok).toBe(true);
      expect((await readdir(dir)).some((f) => f.includes('.bak'))).toBe(false);
      // The SAME backup path was reused (rolling), not a second file created
      // — and it now holds the state from just before the SECOND write (i.e.
      // it changed, proving it really did roll rather than staying stale).
      const backupAfterSecond = await readFile(backupPath);
      expect(backupAfterSecond.equals(backupAfterFirst)).toBe(false);
    });
  });
});

describe('xlsx-comments write — ambiguous existing comment wiring is refused, not guessed at', () => {
  it('a vmlDrawing relationship with no matching comments relationship refuses rather than risking a guess', async () => {
    // Uses the kitchen-sink fixture's "Notes" sheet, which starts with ZERO
    // comment wiring of its own (no rels file, no <legacyDrawing> at all) —
    // so injecting only a vmlDrawing relationship + <legacyDrawing>, with NO
    // comments relationship, creates GENUINE ambiguity rather than risking a
    // false negative by injecting a SECOND entry alongside a real sheet's
    // own already-consistent wiring (`elementsByTag(...)[0]`/`.find()` would
    // simply find the pre-existing legitimate one first).
    const zip = await JSZip.loadAsync(await loadKitchenSinkFixture());
    const fakeRels = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rIdFakeVml" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/vmlDrawing" Target="../drawings/vmlDrawing99.vml"/></Relationships>';
    zip.file('xl/worksheets/_rels/sheet2.xml.rels', fakeRels);
    zip.file(
      'xl/drawings/vmlDrawing99.vml',
      '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><xml xmlns:v="urn:schemas-microsoft-com:vml" xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel"></xml>'
    );
    const sheetXml = await zip.file('xl/worksheets/sheet2.xml')!.async('string');
    zip.file('xl/worksheets/sheet2.xml', sheetXml.replace('</worksheet>', '<legacyDrawing r:id="rIdFakeVml"/></worksheet>'));
    const before = await zip.generateAsync({ type: 'nodebuffer' });

    await withScratchCopy(
      async (target) => {
        const result = await addXlsxComment({
          absolutePath: target,
          path: 'reports/ambiguous.xlsx',
          selector: cellSelector('A1', 'Notes'),
          text: 'x',
          author: 'user',
        });
        expect(result).toEqual({ ok: false, error: 'ambiguous-comment-wiring' });
        expect(await readFile(target)).toEqual(before);
      },
      before,
      'ambiguous.xlsx'
    );
  });
});

// =============================================================================
// Kitchen-sink byte-identity pinning tests — the whole point of this
// session's rewrite. xlsx-kitchen-sink.xlsx (built by real LibreOffice, see
// this file's own header) carries exactly the OOXML surface the OLD
// exceljs-based writer was proven to lose: a custom document property, a
// defined name with an absolute ($) reference, merged cells, column widths,
// a hidden row, frozen panes, conditional formatting, data validation, a
// hyperlink, an embedded image, sheet protection, rich text, and a
// PRE-EXISTING, deliberately resized comment on Data!E1. For every
// add/reply/resolve/reopen/move below: every part except the ones the
// operation legitimately touches must be byte-identical to the input, the
// pre-existing resized comment's shape must be untouched, and the output
// must open in a real LibreOffice and round-trip through the reader.
// =============================================================================
describe('xlsx-comments write — kitchen-sink fixture: real-world OOXML survives untouched', () => {
  // The exact style string build-xlsx-kitchen-sink.py's own generator
  // deliberately set on Data!E1's note — different from BOTH LibreOffice's
  // own default and this app's own default (`width:97.8pt;height:59.1pt`) —
  // so a test that failed to preserve it would be caught immediately.
  const RESIZED_SHAPE_STYLE =
    'position:absolute;margin-left:85.05pt;margin-top:5.65pt;width:170.05pt;height:113.35pt;mso-wrap-style:none;v-text-anchor:middle;visibility:hidden';

  async function resizedShapeStyle(bytes: Buffer): Promise<string | undefined> {
    const zip = await JSZip.loadAsync(bytes);
    const vmlXml = await zip.file('xl/drawings/vmlDrawing1.vml')!.async('string');
    const doc = vmlXml; // plain string scan is enough — we only need the one attribute value
    const m = /<v:shape\b[^>]*\bstyle="([^"]*)"[^>]*>\s*<v:shadow[\s\S]*?<x:Row>0<\/x:Row><x:Column>4<\/x:Column>/.exec(doc);
    return m?.[1];
  }

  it('add on a DIFFERENT cell of the ALREADY-commented "Data" sheet leaves every other part untouched, and the resized comment exactly as it was', async () => {
    await withKitchenSinkScratchCopy(async (target) => {
      const before = await readFile(target);
      expect(await resizedShapeStyle(before)).toBe(RESIZED_SHAPE_STYLE);

      const result = await addXlsxComment({
        absolutePath: target,
        path: 'reports/xlsx-kitchen-sink.xlsx',
        selector: cellSelector('A1', 'Data'),
        text: 'Double check this figure.',
        author: 'user',
      });
      expect(result.ok).toBe(true);
      if (!result.ok) return;
      const after = await readFile(target);

      // Only the parts a legacy note on an ALREADY-wired sheet needs are
      // allowed to change — the worksheet's own XML is untouched (legacyDrawing
      // already existed), so only comments1.xml/vmlDrawing1.vml change.
      await assertOnlyThesePartsChanged(before, after, ['xl/comments1.xml', 'xl/drawings/vmlDrawing1.vml']);
      // The pre-existing resized comment's own shape is untouched.
      expect(await resizedShapeStyle(after)).toBe(RESIZED_SHAPE_STYLE);

      await assertOpensInLibreOffice(after);
      const read = await readXlsxComments(after, 'reports/xlsx-kitchen-sink.xlsx');
      expect(read.ok).toBe(true);
      if (!read.ok) return;
      const added = read.comments.find((c) => c.id === result.id);
      expect(added?.text).toBe('Double check this figure.');
      // The pre-existing resized comment still reads back too.
      const resized = read.comments.find((c) => c.selector.kind === 'cell' && c.selector.selector.cell === 'E1');
      expect(resized?.text).toContain('deliberately resized');
    });
  });

  it('add on the "Notes" sheet, which has NO notes yet, wires a brand-new comments/VML pair and touches nothing on "Data"', async () => {
    await withKitchenSinkScratchCopy(async (target) => {
      const before = await readFile(target);
      const beforeNames = new Set(await zipEntryNames(before));
      expect(beforeNames.has('xl/comments2.xml')).toBe(false);
      expect(beforeNames.has('xl/drawings/vmlDrawing2.vml')).toBe(false);

      const result = await addXlsxComment({
        absolutePath: target,
        path: 'reports/xlsx-kitchen-sink.xlsx',
        selector: cellSelector('A1', 'Notes'),
        text: 'First note on this sheet.',
        author: 'user',
      });
      expect(result.ok).toBe(true);
      if (!result.ok) return;
      const after = await readFile(target);

      // "Data" sheet's own parts (worksheet XML, comments1.xml,
      // vmlDrawing1.vml, its own rels) — and every unrelated part — are
      // untouched. The NEW parts (comments2.xml, vmlDrawing2.vml, the
      // "Notes" worksheet itself gaining <legacyDrawing>, its own brand-new
      // rels file, and [Content_Types].xml) are the only allowed changes.
      await assertOnlyThesePartsChanged(before, after, [
        'xl/worksheets/sheet2.xml',
        'xl/worksheets/_rels/sheet2.xml.rels',
        'xl/comments2.xml',
        'xl/drawings/vmlDrawing2.vml',
        '[Content_Types].xml',
      ]);
      expect(await resizedShapeStyle(after)).toBe(RESIZED_SHAPE_STYLE);

      await assertOpensInLibreOffice(after);
      const read = await readXlsxComments(after, 'reports/xlsx-kitchen-sink.xlsx');
      expect(read.ok).toBe(true);
      if (!read.ok) return;
      const added = read.comments.find((c) => c.id === result.id);
      expect(added?.text).toBe('First note on this sheet.');
    });
  });

  it('reply/resolve/reopen on the pre-existing resized comment itself only ever touches comments1.xml, never its shape', async () => {
    await withKitchenSinkScratchCopy(async (target) => {
      const before = await readFile(target);
      const beforeRead = await readXlsxComments(before, 'reports/xlsx-kitchen-sink.xlsx');
      if (!beforeRead.ok) throw new Error('setup: fixture failed to read');
      const resized = beforeRead.comments.find((c) => c.selector.kind === 'cell' && c.selector.selector.cell === 'E1')!;

      const replied = await replyToXlsxComment({
        absolutePath: target,
        path: 'reports/xlsx-kitchen-sink.xlsx',
        id: resized.id,
        text: 'Noted — leaving this box as-is.',
        author: 'user',
      });
      expect(replied).toEqual({ ok: true });
      const afterReply = await readFile(target);
      await assertOnlyThesePartsChanged(before, afterReply, ['xl/comments1.xml']);
      // The SHAPE (position/size) is untouched even though the comment TEXT
      // changed — reply only ever edits <comment>/<text>, never <v:shape>.
      expect(await resizedShapeStyle(afterReply)).toBe(RESIZED_SHAPE_STYLE);

      const resolved = await resolveXlsxComment({ absolutePath: target, path: 'reports/xlsx-kitchen-sink.xlsx', id: resized.id });
      expect(resolved).toEqual({ ok: true });
      const afterResolve = await readFile(target);
      await assertOnlyThesePartsChanged(before, afterResolve, ['xl/comments1.xml']);

      const reopened = await reopenXlsxComment({ absolutePath: target, path: 'reports/xlsx-kitchen-sink.xlsx', id: resized.id });
      expect(reopened).toEqual({ ok: true });
      const afterReopen = await readFile(target);
      await assertOnlyThesePartsChanged(before, afterReopen, ['xl/comments1.xml']);
      expect(await resizedShapeStyle(afterReopen)).toBe(RESIZED_SHAPE_STYLE);

      await assertOpensInLibreOffice(afterReopen);
      const read = await readXlsxComments(afterReopen, 'reports/xlsx-kitchen-sink.xlsx');
      expect(read.ok).toBe(true);
      if (!read.ok) return;
      const note = read.comments.find((c) => c.id === resized.id);
      expect(note?.resolved).toBe(false);
      expect(note?.replies.some((r) => r.text === 'Noted — leaving this box as-is.')).toBe(true);
    });
  });

  it('move relocates the resized comment to a fresh cell, and the moved copy is a plain default-sized shape — never the old resized style silently reused for a new position it no longer matches', async () => {
    await withKitchenSinkScratchCopy(async (target) => {
      const before = await readFile(target);
      const beforeRead = await readXlsxComments(before, 'reports/xlsx-kitchen-sink.xlsx');
      if (!beforeRead.ok) throw new Error('setup: fixture failed to read');
      const resized = beforeRead.comments.find((c) => c.selector.kind === 'cell' && c.selector.selector.cell === 'E1')!;

      const result = await moveXlsxComment({
        absolutePath: target,
        path: 'reports/xlsx-kitchen-sink.xlsx',
        id: resized.id,
        newSelector: cellSelector('G3', 'Data'), // has a real value (30, conditional-formatting range) and no note
      });
      expect(result).toEqual({ ok: true });
      const after = await readFile(target);
      await assertOnlyThesePartsChanged(before, after, ['xl/comments1.xml', 'xl/drawings/vmlDrawing1.vml']);

      await assertOpensInLibreOffice(after);
      const read = await readXlsxComments(after, 'reports/xlsx-kitchen-sink.xlsx');
      expect(read.ok).toBe(true);
      if (!read.ok) return;
      expect(read.comments.some((c) => c.selector.kind === 'cell' && c.selector.selector.cell === 'E1')).toBe(false);
      const moved = read.comments.find((c) => c.selector.kind === 'cell' && c.selector.selector.cell === 'G3');
      expect(moved?.text).toBe(resized.text);
    });
  });
});
